#include <algorithm>
#include <cmath>
#include <iomanip>
#include <iostream>

struct Call {
    double operator()(double S, double K) const { return std::max(S - K, 0.0); }
};

int main() {
    const double S = 100.0, K = 100.0, r = 0.05, T = 1.0;
    const double up = 110.0, down = 90.0;  // the only two prices the stock can reach
    const double payUp = Call{}(up, K), payDown = Call{}(down, K);

    // The hedge: delta shares, plus cash that grows to cashLater by expiry.
    const double delta = (payUp - payDown) / (up - down);
    const double cashLater = payUp - delta * up;
    const double cash = cashLater * std::exp(-r * T);  // negative: borrowed today
    std::cout << std::fixed << std::setprecision(4);
    std::cout << "hold " << delta << " shares and " << cash << " in cash" << '\n';
    std::cout << "the hedge pays " << delta * up + cashLater << " up, " << delta * down + cashLater << " down" << '\n';
    std::cout << "the call pays  " << payUp << " up, " << payDown << " down" << '\n';
    std::cout << "cost of the hedge " << delta * S + cash << '\n';

    // The same price as a discounted average, with the odds that make the stock fair.
    const double p = (S * std::exp(r * T) - down) / (up - down);
    const double average = p * payUp + (1 - p) * payDown;
    std::cout << "risk-neutral p " << p << ", discounted average " << std::exp(-r * T) * average << '\n';
    return 0;
}

