#include <algorithm>
#include <cmath>
#include <iomanip>
#include <iostream>
#include <vector>

struct Call {
    double operator()(double S, double K) const { return std::max(S - K, 0.0); }
};

struct Put {
    double operator()(double S, double K) const { return std::max(K - S, 0.0); }
};

struct Market {
    double S0, K, r, sigma, T;  // spot, strike, rate, volatility, years to expiry
};

// An n-step CRR tree. An American option takes the better of holding and exercising
// at every node, a European one only holds.
template <typename Payoff>
double crr_price(const Payoff& payoff, const Market& m, int n, bool american) {
    const double dt = m.T / n;
    const double u = std::exp(m.sigma * std::sqrt(dt));
    const double d = 1.0 / u;
    const double p = (std::exp(m.r * dt) - d) / (u - d);
    const double disc = std::exp(-m.r * dt);
    std::vector<double> v(n + 1);
    for (int j = 0; j <= n; ++j) {
        v[j] = payoff(m.S0 * std::pow(u, 2 * j - n), m.K);
    }
    for (int i = n - 1; i >= 0; --i) {
        for (int j = 0; j <= i; ++j) {
            const double hold = disc * (p * v[j + 1] + (1 - p) * v[j]);
            const double exercise = payoff(m.S0 * std::pow(u, 2 * j - i), m.K);  // this node's price
            v[j] = american ? std::max(hold, exercise) : hold;
        }
    }
    return v[0];
}

int main() {
    const int n = 500;
    std::cout << std::fixed << std::setprecision(4);
    std::cout << "spot  european  american  premium  exercise now" << '\n';
    for (double S : {60.0, 80.0, 90.0, 100.0, 110.0, 120.0}) {
        const Market m{S, 100.0, 0.05, 0.20, 1.0};
        const double eu = crr_price(Put{}, m, n, false);
        const double am = crr_price(Put{}, m, n, true);
        std::cout << std::setw(4) << std::setprecision(0) << S << std::setprecision(4) << std::setw(10) << eu
                  << std::setw(10) << am << std::setw(9) << am - eu << std::setw(14) << Put{}(S, m.K) << '\n';
    }
    const Market atm{100.0, 100.0, 0.05, 0.20, 1.0};
    std::cout << "call: european " << crr_price(Call{}, atm, n, false) << ", american " << crr_price(Call{}, atm, n, true) << '\n';
    return 0;
}

